import data from "@/lib/verified/universe.json";

/**
 * Companies kept in the permanent fundamentals store without anyone having to open them:
 * the 1000 largest worldwide and the 1000 largest US-listed (generated by
 * scripts/build-universe.mjs, largest first). Any other company joins the store the first
 * time somebody views it.
 */
export type UniverseEntry = {
  /** Yahoo-format symbol. */
  s: string;
  n: string;
  /** Country (empty for US-list entries that are not in the world ranking). */
  c: string;
  /** Rank in the world top 1000. */
  w?: number;
  /** Rank in the US top 1000. */
  u?: number;
};

export const UNIVERSE: readonly UniverseEntry[] = data as UniverseEntry[];

const SET = new Set(UNIVERSE.map((u) => u.s));

export function isInUniverse(symbol: string): boolean {
  return SET.has(symbol.trim().toUpperCase());
}
